    print("Models defined successfully!")
    print(f"Parent: {Parent}")
    print(f"ProxyParent: {ProxyParent}")
    print(f"Child: {Child}")
    print(f"ManyToManyModel: {ManyToManyModel}")
    print("Issue is fixed!")
